class Calendar {
  constructor() {
    // assume compression and BIT initialization here
    this.bit = new Fenwick(/* size */);
    this.idMap = new Map();
    this.nextId = 1;
  }
  addReservation(l, r) {
    const id = this.nextId++;
    const [li, ri] = this._idx(l, r);
    this.idMap.set(id, [li, ri]);
    this.bit.add(li, 1);
    this.bit.add(ri, -1);
